/// Is `url` in one of HL7's own spaces — where an unknown value is a typo, not a local system?
pub fn in_known_space(url: &str) -> bool {
    url.starts_with("http://hl7.org/fhir")
        || url.starts_with("http://terminology.hl7.org/")
        || url.starts_with("http://fhir.org/guides")
}

/// Is `url` (a version suffix `|x` or a fragment `#x` dropped) a definition the packages hold?
pub fn known_definition(url: &str) -> bool {
    let url = url.split(['|', '#']).next().unwrap_or(url);
    let mut h: u32 = 0x811c9dc5;
    for b in url.bytes() {
        h = (h ^ u32::from(b)).wrapping_mul(0x01000193);
    }
    KNOWN_SPACE_URLS.binary_search(&h).is_ok()
}
